function applyMslPhoto(role){const ids=mslPhotoIds(role),value=Math.max(0,Number($(ids.value)?.value)||0),marking=String($(ids.marking)?.value||'').trim(),target=role==='cargo'?$('quickCargoMsl'):$('quickCtuMsl'),targetId=role==='cargo'?'quickCargoMsl':'quickCtuMsl',status=$(ids.status),state=quickMslPhotoState[role];if(!state){if(status)status.textContent='先に写真を撮影またはアップロードしてください。';return}if(value<=0){if(status)status.textContent='写真・資料で確認したMSLを入力してください。';$(ids.value)?.focus();return}if(!marking){if(status)status.textContent='写真で確認した刻印・表示、または照合した図面・仕様を入力してください。';$(ids.marking)?.focus();return}target.value=value.toFixed(1);quickMslEstimateState[role]={role,profileId:'photo-confirmed',material:'photo-evidence',size:marking,nominalStrengthKn:value,factor:1,candidateMslKn:value,evidence:'photo-marking',confirmed:true,appliedAt:new Date().toISOString(),source:'撮影・アップロード写真＋刻印・表示／資料照合',photo:{fingerprint:state.fingerprint,fileName:state.fileName,width:state.width,height:state.height,marking}};if(status)status.innerHTML=`<strong>${value.toFixed(1)} kNを反映しました。</strong><br>写真と刻印・表示の確認記録を算出結果へ保持します。`;invalidateCtuReview?.();window.dispatchEvent(new CustomEvent('sk:ctu-system-applied',{detail:{source:'msl-photo-confirmed',fields:[targetId]}}));window.dispatchEvent(new CustomEvent('sk:ctu-photo-applied',{detail:{source:'msl-photo-confirmed',fields:[targetId]}}))}
