const MSL_POINT_EVIDENCE={marking:'刻印・銘板',drawing:'図面・仕様書',manufacturer:'メーカー資料',certificate:'強度証明書・試験成績',ctuApproval:'CTU承認資料',shipper:'荷主提出資料',manual:'手入力',unknown:'確認できない'};
