const mslPointRegistryState={records:[],draftPhotos:[],applicationId:null,history:[],annotationPhotoIndex:null};
function mslPointToKn(value,unit){const n=Math.max(0,Number(value)||0);return n*(MSL_UNIT_TO_KN[unit]||0)}
