function mslPointActive(row){return Boolean(row?.planned)&&row?.condition==='normal'&&Number(row?.mslKn)>0&&row?.evidence!=='unknown'&&!['revision','unusable'].includes(row?.reviewStatus||'unconfirmed')}
function nextMslPointNumber(role){const prefix=role==='cargo'?'貨物側':'CTU側',used=mslPointRegistryState.records.filter(x=>x.role===role).map(x=>Number(String(x.pointNumber||'').match(/(\d+)$/)?.[1])||0);return `${prefix}-${Math.max(0,...used)+1}`}
function updateMslPointNumber(){const role=$('mslPointRole')?.value||'cargo';if($('mslPointNumber'))$('mslPointNumber').value=nextMslPointNumber(role)}
function mslPointRegistrySnapshot(){return mslPointRegistryState.records.map(row=>({id:row.id,role:row.role,pointNumber:row.pointNumber,name:row.name,location:row.location,pointType:row.pointType,lineIds:[...row.lineIds],sameSpecificationCount:row.sameSpecificationCount,originalValue:row.originalValue,unit:row.unit,mslKn:row.mslKn,evidence:row.evidence,marking:row.marking,condition:row.condition,planned:row.planned,duplicateUseConfirmed:row.duplicateUseConfirmed,note:row.note,reviewStatus:row.reviewStatus||'unconfirmed',reviewedBy:row.reviewedBy||'',reviewedAt:row.reviewedAt||null,reviewNote:row.reviewNote||'',photos:row.photos.map(photo=>({savedPhotoId:photo.savedPhotoId||null,fingerprint:photo.fingerprint,fileName:photo.fileName,width:photo.width,height:photo.height,fileSize:photo.fileSize,kind:photo.kind||'overall',markers:Array.isArray(photo.markers)?photo.markers.map(m=>({type:m.type,x:Number(m.x)||0,y:Number(m.y)||0,createdAt:m.createdAt||null})):[]})),createdAt:row.createdAt,updatedAt:row.updatedAt}))}
function mslPointRegistryWarnings(warnings){mslPointRegistryState.records.forEach(row=>{const label=`${row.pointNumber}${row.name?'（'+row.name+'）':''}`;if(row.condition!=='normal'&&row.planned)warnings.add(`${label}：${MSL_POINT_CONDITIONS[row.condition]||row.condition}のため、採用MSLの計算対象から除外しています。`);if(row.evidence==='unknown'&&row.planned)warnings.add(`${label}：MSLの確認根拠がありません。計算対象から除外しています。`);if(row.lineIds.length>1&&!row.duplicateUseConfirmed)warnings.add(`${label}：同一取付点が複数の固縛ラインに指定されています。重複使用の確認が必要です。`);if(mslPointActive(row)&&(row.reviewStatus||'unconfirmed')!=='confirmed')warnings.add(`${label}：取付点MSLは未確認です。算出結果を登録する前に写真・刻印・資料と照合してください。`)})}
