const MSL_POINT_REVIEW_STATUS={unconfirmed:'未確認',confirmed:'確認済み',revision:'修正依頼',unusable:'使用不可'};
const MSL_PHOTO_KINDS={overall:'取付部全体',location:'取付位置',marking:'刻印・銘板',secured:'固縛後の状態',damage:'損傷確認',other:'その他'};
const MSL_MARKER_TYPES={use:'使用する取付点',msl:'MSL表示箇所',review:'確認が必要',damage:'損傷箇所',unused:'使用しない取付点'};
function mslPointHistorySnapshot(){return (mslPointRegistryState.history||[]).slice(-200).map(row=>({id:row.id,at:row.at,action:row.action,pointId:row.pointId||null,pointNumber:row.pointNumber||'',actor:row.actor||'',note:row.note||'',reviewStatus:row.reviewStatus||null,mslKn:Number(row.mslKn)||0}))}
