function renderMslPointReviewPanel(){const box=$('mslPointReviewSummary'),badge=$('mslPointReviewBadge'),history=$('mslPointHistoryList');if(!box)return;const rows=mslPointRegistryState.records,active=rows.filter(mslPointActive),confirmed=active.filter(x=>(x.reviewStatus||'unconfirmed')==='confirmed'),revision=rows.filter(x=>(x.reviewStatus||'')==='revision'),unusable=rows.filter(x=>(x.reviewStatus||'')==='unusable'),ready=mslPointReviewReady();box.innerHTML=`<div><span>計算対象</span><strong>${active.length}件</strong></div><div><span>確認済み</span><strong>${confirmed.length}件</strong></div><div><span>修正依頼</span><strong>${revision.length}件</strong></div><div><span>使用不可</span><strong>${unusable.length}件</strong></div>`;if(badge){badge.textContent=ready?'確認完了':'未確認あり';badge.classList.toggle('is-ready',ready)}if(history){const labels={created:'登録',confirmed:'確認済み',revision:'修正依頼',unusable:'使用不可',deleted:'削除'};history.innerHTML=(mslPointRegistryState.history||[]).length?[...mslPointRegistryState.history].reverse().slice(0,50).map(h=>`<div class="msl-history-row"><time>${esc(new Date(h.at).toLocaleString('ja-JP'))}</time><strong>${esc(h.pointNumber||'台帳')}</strong><span>${esc(labels[h.action]||h.action)}</span><span>${esc(h.actor||'―')}</span><p>${esc(h.note||'')}</p></div>`).join(''):'<p class="msl-point-empty">変更・確認履歴はありません。</p>'}updateCtuReview?.()}
function reviewMslPointRecord(id,status){const row=mslPointRegistryState.records.find(x=>x.id===id),actor=String($('mslPointReviewer')?.value||'').trim(),note=String($('mslPointReviewNote')?.value||'').trim(),message=$('mslPointStatus');if(!row)return;if(!actor){message.textContent='確認者名を入力してください。';$('mslPointReviewer')?.focus();return}if(status==='confirmed'&&(row.condition!=='normal'||row.evidence==='unknown'||Number(row.mslKn)<=0)){message.textContent='異常・確認不能・MSL未入力の取付点は確認済みにできません。';return}if(['revision','unusable'].includes(status)&&!note){message.textContent='修正依頼または使用不可の場合は、確認メモへ理由を入力してください。';$('mslPointReviewNote')?.focus();return}row.reviewStatus=status;row.reviewedBy=actor;row.reviewedAt=new Date().toISOString();row.reviewNote=note;row.updatedAt=row.reviewedAt;mslPointAddHistory(status,row,note,actor);persistMslPointRegistry();renderMslPointRegistry();message.innerHTML=`<strong>${esc(row.pointNumber)}を「${esc(MSL_POINT_REVIEW_STATUS[status])}」に更新しました。</strong>`;invalidateCtuReview?.()}
function closeMslPointAnnotation(){mslPointRegistryState.annotationPhotoIndex=null;const p=$('mslPointAnnotationPanel');if(p)p.hidden=true}
function openMslPointAnnotation(index){const photo=mslPointRegistryState.draftPhotos[index],panel=$('mslPointAnnotationPanel');if(!photo?.dataUrl||!panel)return;mslPointRegistryState.annotationPhotoIndex=index;panel.hidden=false;if($('mslPointPhotoKind'))$('mslPointPhotoKind').value=photo.kind||'overall';drawMslPointAnnotation();panel.scrollIntoView?.({behavior:'smooth',block:'nearest'})}
function drawMslPointAnnotation(){const idx=mslPointRegistryState.annotationPhotoIndex,photo=mslPointRegistryState.draftPhotos[idx],canvas=$('mslPointAnnotationCanvas');if(!photo?.dataUrl||!canvas)return;const image=new Image();image.onload=()=>{const max=1200,scale=Math.min(1,max/image.naturalWidth,max/image.naturalHeight);canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);const colors={use:'#0b6b3a',msl:'#0b4fa3',review:'#a56a00',damage:'#b3261e',unused:'#616161'};(photo.markers||[]).forEach((m,i)=>{const x=m.x*canvas.width,y=m.y*canvas.height;ctx.beginPath();ctx.fillStyle=colors[m.type]||'#103b66';ctx.arc(x,y,Math.max(9,canvas.width*.012),0,Math.PI*2);ctx.fill();ctx.lineWidth=Math.max(2,canvas.width*.002);ctx.strokeStyle='#fff';ctx.stroke();ctx.font=`bold ${Math.max(12,Math.round(canvas.width*.018))}px sans-serif`;ctx.fillStyle='#fff';ctx.fillText(String(i+1),x-Math.max(4,canvas.width*.004),y+Math.max(5,canvas.width*.005));ctx.font=`bold ${Math.max(12,Math.round(canvas.width*.016))}px sans-serif`;ctx.fillStyle=colors[m.type]||'#103b66';ctx.fillText(MSL_MARKER_TYPES[m.type]||m.type,x+Math.max(13,canvas.width*.016),y-Math.max(10,canvas.width*.008))});const st=$('mslPointAnnotationStatus');if(st)st.textContent=`${MSL_PHOTO_KINDS[photo.kind||'overall']}：マーカー ${(photo.markers||[]).length}件。写真上をタップして追加できます。`};image.src=photo.dataUrl}
function addMslPointMarker(event){const idx=mslPointRegistryState.annotationPhotoIndex,photo=mslPointRegistryState.draftPhotos[idx],canvas=$('mslPointAnnotationCanvas');if(!photo||!canvas)return;const rect=canvas.getBoundingClientRect(),x=Math.min(1,Math.max(0,(event.clientX-rect.left)/rect.width)),y=Math.min(1,Math.max(0,(event.clientY-rect.top)/rect.height)),type=$('mslPointMarkerType')?.value||'use';photo.markers??=[];photo.markers.push({type,x,y,createdAt:new Date().toISOString()});drawMslPointAnnotation();renderMslPointDraftPhotos()}
