function clearMslPointMarkers(){const photo=mslPointRegistryState.draftPhotos[mslPointRegistryState.annotationPhotoIndex];if(!photo)return;if(photo.markers?.length&&!confirm('この写真のマーカーをすべて削除しますか。'))return;photo.markers=[];drawMslPointAnnotation();renderMslPointDraftPhotos()}
