function exportMslPointCsv(){const app=selectedMslRegistryApplication(),rows=mslPointRegistryState.records;if(!rows.length){$('mslPointStatus').textContent='CSVへ出力する取付点がありません。';return}const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',header=['区分','取付点番号','名称','位置','種類','固縛ライン','入力値','単位','換算MSL(kN)','確認根拠','刻印・表示','状態','確認状態','確認者','確認日時','写真枚数','マーカー数','備考'],body=rows.map(r=>[mslPointRoleLabel(r.role),r.pointNumber,r.name,r.location,r.pointType,(r.lineIds||[]).join('|'),r.originalValue,r.unit,Number(r.mslKn||0).toFixed(3),MSL_POINT_EVIDENCE[r.evidence]||r.evidence,r.marking,MSL_POINT_CONDITIONS[r.condition]||r.condition,MSL_POINT_REVIEW_STATUS[r.reviewStatus||'unconfirmed'],r.reviewedBy,r.reviewedAt||'',r.photos.length,r.photos.reduce((n,p)=>n+(p.markers||[]).length,0),r.note].map(q).join(',')),csv='\uFEFF'+[header.map(q).join(','),...body].join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a'),caseNo=app?`${app.applicationYear||''}-${app.applicationNumber||''}`:'unassigned';a.href=url;a.download=`MSL取付点台帳_${caseNo}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('mslPointStatus').textContent='取付点MSL台帳CSVを出力しました。'}

function initMslEstimators(){Object.keys(MSL_ROLE_PREFIX).forEach(role=>{const ids=mslIds(role);populateMslMaterials(role);$(ids.material)?.addEventListener('change',()=>populateMslProfiles(role));$(ids.profile)?.addEventListener('change',()=>updateMslCandidate(role));$(ids.nominal)?.addEventListener('input',()=>updateMslCandidate(role));$(ids.factor)?.addEventListener('input',()=>updateMslCandidate(role));$(ids.apply)?.addEventListener('click',()=>applyMslCandidate(role));const target=mslRoleConfig(role)?.targetInput?$(mslRoleConfig(role).targetInput):null;target?.addEventListener('input',event=>{if(event.isTrusted)quickMslEstimateState[role]=null})})}
function quickMslWarnings(warnings){Object.values(quickMslEstimateState).filter(Boolean).forEach(row=>{if(!row.confirmed)warnings.add(`${row.role==='device'?'固縛材':row.role==='cargo'?'貨物側取付部':'CTU側固縛点'}：材質・サイズマスターから算出した ${Number(row.candidateMslKn).toFixed(1)} kN は参考候補です。メーカー仕様、刻印、証明書または試験成績で確認してください。`)})}
