$('createAndSaveCtuResult').onclick=()=>{try{const app=createCtuCaseInformation();calc();latestCtuResult.review=window.SKCTUReview.getData();latestCtuResult.applicationCase=currentCtuCasePayload();const row=window.ISSApplicationResults.save(app.id,'ctu-securing','固縛力参考算出結果',latestCtuResult);$('ctuRegistrationMessage').textContent=`申請番号 ${row.applicationYear}-${row.applicationNumber} を新規登録し、共通案件情報と算出結果を保存しました。`;window.dispatchEvent(new CustomEvent('sk:ctu-calculated',{detail:{source:'advanced-create-save',at:new Date().toISOString()}}));window.dispatchEvent(new CustomEvent('sk:ctu-registered',{detail:{applicationId:app.id,applicationYear:row.applicationYear,applicationNumber:row.applicationNumber,at:new Date().toISOString()}}));}catch(e){$('ctuRegistrationMessage').textContent=e.message||'新規登録できませんでした。'}};
